from h import *
R(9772614,"حساء الدجاج النباتي بالجاك فروت والبطاطس",
"الجاك فروت والبطاطس والأرز البني وكمية وفيرة من الخضار تجعل منه طبق حساء دجاج نباتي مشبعًا!",
"8 حصص","حصة واحدة",
["1 بصلة حمراء مفرومة ناعمًا","2 جزرة كبيرة مقشرة ومقطعة إلى مكعبات","2 ساق كرفس مقطعة إلى مكعبات","200 غرام فطر كريميني مقطع إلى شرائح، حوالي 6-8 حبات فطر","2 حبة فلفل رومي مقطعة إلى مكعبات، بأي لون","2 رطل بطاطس صفراء مقشرة ومقطعة إلى مكعبات (حوالي 4-5 أكواب من البطاطس المقطعة)","علبة جاك فروت أخضر صغير (غير ناضج) وزنها 20 أونصة في محلول ملحي أو ماء، وليس في شراب","1 كوب أرز بني","10 أكواب مرق خضار قليل الصوديوم","3 أوراق غار","¼ ملعقة صغيرة زعتر مجفف","¼ ملعقة صغيرة إكليل الجبل (روزماري) مجفف","¼ ملعقة صغيرة ريحان مجفف","¼ ملعقة صغيرة مريمية مجففة","¼ ملعقة صغيرة أوريجانو مجفف","ملح وفلفل حسب الرغبة","عبوة توفو متوسط الصلابة وزنها 454 غرام، اختر نوعًا خاليًا من التعديل الوراثي إن أمكن"],
["ضع البصل المفروم والجزر والكرفس والفلفل والفطر في قدر كبير مع ملعقة كبيرة أو ملعقتين من الماء. قلّبها على نار متوسطة حتى تلين، حوالي 5-8 دقائق.",
"أضف جميع المكونات المتبقية، باستثناء التوفو، إلى القدر واتركها حتى تغلي. وعند الغليان، اخفض الحرارة واتركها على نار هادئة حتى ينضج الأرز، حوالي 30 دقيقة. أخرج أوراق الغار بعد النضج.",
"في الأثناء، اهرس التوفو في الخلاط، وأضف قطرة أو قطرتين من الماء عند الحاجة لتسهيل الخلط. وعندما ينضج الحساء، أطفئ النار وحرّك فيه التوفو حتى يمتزج.",
"تذوّق وأضف الملح والفلفل عند الحاجة."],
["يمكنك استبدال البطاطس بالبطاطا الحلوة إن فضّلت. لاحظ أن ذلك سيجعل نكهة الحساء أحلى. أفضّل التوفو متوسط الصلابة لأنه يُثخّن الحساء جيدًا. لكن استخدم ما لديك. كما يصلح التوفو الطري أو الحريري. وللحصول على وصفة خالية من الصويا، استبدل التوفو بعلبة من الفاصولياء البيضاء المخلوطة (الكلى البيضاء أو الكانيليني). أو استخدم كوبًا تقريبًا من حليبك النباتي المفضل. لاحظ أن خيار الحليب لن يُثخّن المرق، لكنه سيضيف كريمية إضافية. وإذا أردت رفع محتوى البروتين، فيُنصح باستخدام التوفو أو الفاصولياء. استخدم محضّرة الطعام لفرم الخضار ناعمًا إذا كنت تطعم أطفالًا انتقائيين في الطعام. وإذا فضّلت قوامًا يشبه اليخنة، فقطّع الخضار يدويًا إلى قطع أكبر قليلًا. وإذا كنت لا تحب التوفو، فلا تقلق! أعدك بأنك لن تشعر بطعمه في الحساء. فالتوفو يضيف كريمية ونعومة رائعتين دون أن يغيّر النكهة. (ولكن إذا كنت لا تستطيع تناول الصويا لأسباب صحية، فراجع اقتراحات الاستبدال أعلاه.) يمكنك التحضير مسبقًا بتقطيع جميع الخضار قبل يوم واحد. فقط احتفظ بالبطاطس في الماء بعد تقشيرها وتقطيعها لمنعها من الاسمرار. يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام أو يُجمَّد لمدة تصل إلى شهرين في وعاء محكم الإغلاق."],
{})
R(9774483,"باستا راستا النباتية",
"استمتع بنكهات الكاريبي النابضة بالحياة مع باستا راستا النباتية اللذيذة.",
"5 حصص","حصة واحدة",
["½ رطل معكرونة بيني أو أي شكل معكرونة تفضله","¼ كوب مرق خضار","1 بصلة صفراء مفرومة ناعمًا","3 حبات فلفل رومي بأي لون","4 فصوص ثوم مفرومة","2 ملعقة كبيرة بهارات جيرك","2 ملعقة صغيرة بابريكا مدخنة","1 كوب مرق خضار","1 كوب صلصة طماطم","1.5 كوب حمص مطبوخ أو معلب (حوالي علبة واحدة 15 أونصة)","1 كوب حليب جوز الهند من Thai Kitchen","جبن بارميزان نباتي","فلفل أسود أو رقائق الفلفل الأحمر"],
["اترك قدرًا كبيرًا من الماء حتى يغلي واطبخ المعكرونة وفق تعليمات العبوة للحصول على معكرونة «ألدنتي». وبعد النضج، صفّها واتركها جانبًا.",
"في الأثناء، ضع ¼ كوب من المرق والبصل والفلفل المقطع إلى شرائح في مقلاة كبيرة وقلّبها حتى تلين قليلًا، حوالي 5-7 دقائق. ثم أضف الثوم وقلّب 30-60 ثانية أخرى مع التحريك المتكرر حتى تفوح رائحته.",
"أضف باقي المرق (كوب واحد) وصلصة الطماطم والحمص وحليب جوز الهند إلى المقلاة واتركها على نار متوسطة لمدة 5-10 دقائق، ثم أطفئ النار.",
"بعد ذلك أضف معكرونة البيني المطبوخة إلى الصلصة وامزج جيدًا لتتغلف المعكرونة بالتساوي. اتركها لبضع دقائق لتمتص المعكرونة بعض الصلصة، ثم قدّمها."],
["غالبًا ما تحتوي خلطات بهارات الجيرك الجاهزة على كمية كبيرة من السكر. حضّر خلطتك بنفسك للتحكم في كمية السكر البني أو احذفه تمامًا إن فضّلت.","اجعل حصصك صغيرة لأن المعكرونة وحليب جوز الهند ثقيلان نسبيًا.","لتقليل الدهون، استخدم حليب جوز الهند الخفيف بدلًا من كامل الدسم. أو يمكنك استخدام حليب آخر خالٍ من الألبان، لكن لاحظ أن الصلصة لن تكون بالغنى نفسه.","أضف الملح إلى ماء سلق المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اطبخ المعكرونة «ألدنتي». لا تفرط في طبخها! «ألدنتي» تعني أن المعكرونة تبقى متماسكة بعد الطبخ، مما يعطي قوامًا مثاليًا في كل لقمة. ولتجنب الإفراط في الطبخ، ابدأ بتذوقها قبل بضع دقائق من الموعد المذكور على العبوة. يجب أن تكون طرية لكن متماسكة.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام."],
{"Optional garnishes":"زينة اختيارية"})
R(9775065,"وافل الحنطة السوداء النباتي",
"استمتع بوافل الحنطة السوداء النباتي، المقرمش والهش وبلا شعور بالذنب!",
"8 قطع وافل","حصة واحدة",
["1.25 كوب حليب الصويا","1 ملعقة كبيرة خل التفاح أو عصير الليمون","180 غرام دقيق الحنطة السوداء (حوالي 1.5 كوب بالملعقة مع تسوية السطح)","1 ملعقة صغيرة قرفة","1 ملعقة صغيرة بيكنغ باودر"],
["سخّن مكواة الوافل على حرارة متوسطة، أو وفق تعليمات الشركة المصنّعة.",
"اخلط حليب الصويا وخل التفاح في وعاء كبير واتركه جانبًا لبضع دقائق. سيثخن الحليب ويتخثر، فتحصل على لبن رائب نباتي.",
"بعد أن يتخثر، أضف جميع المكونات المتبقية إلى الوعاء نفسه وحرّك حتى تمتزج. ثم اطهُ الوافل وفق تعليمات الشركة المصنّعة، حوالي 3-5 دقائق، أو حتى تحصل على درجة النضج المرغوبة.",
"قدّمه مع الإضافات التي تفضلها واستمتع به."],
["زِن الدقيق والبودرة للحصول على أفضل النتائج. فإذا غرفت من الكيس مباشرة، فقد تضيف كمية زائدة وتحتاج إلى مزيد من السائل للحصول على القوام المناسب للعجينة.","إذا لم يكن لديك ميزان مطبخ، فضع الدقيق بالملعقة في كوب القياس وأزل الزائد بسكين.","تأكد من أن مكواة الوافل ساخنة قبل إضافة عجينة الوافل إليها، لتجنب الالتصاق.","لا ترفع الغطاء مبكرًا جدًا وإلا تكسّر الوافل، وارفع الغطاء ببطء وحذر للتحقق من عدم الالتصاق.","تنضج الدفعات اللاحقة من الوافل أسرع قليلًا من الدفعة الأولى، لذا راقبها عن كثب."],
{})
R(9779919,"فاصولياء سوداء في إنستانت بوت [دون نقع]",
"فاصولياء سوداء مثالية في إنستانت بوت في كل مرة ودون حاجة إلى النقع!",
"12 حصة","حصة واحدة",
["1 رطل فاصولياء سوداء جافة مفرزة ومغسولة","6 أكواب ماء عذب أو استخدم المرق لإضافة نكهة"],
["افرز الفاصولياء السوداء الجافة وتخلّص من أي حصى صغير أو شوائب. ثم اغسلها جيدًا وضعها في إنستانت بوت. أضف 6 أكواب من الماء (أو استخدم المرق لإضافة نكهة) إلى الوعاء وأغلق الغطاء، مع التأكد من أن الصمام في وضع الإغلاق.",
"اطبخها بالضغط على الوضع العالي لمدة 30-35 دقيقة (انظر الملاحظات). ستستغرق حوالي 15 دقيقة للوصول إلى الضغط وبدء العدّ التنازلي. وعند انتهاء المؤقت، حرّر الضغط تلقائيًا لمدة 10 دقائق (وليس أكثر) ثم حرّر ما تبقى من البخار بسرعة.",
"افتح الغطاء وصفِّها فورًا لمنع الإفراط في نضج الفاصولياء. استمتع بها مباشرة أو احفظها لأطباق مستقبلية."],
["استخدم فاصولياء طازجة لم تبقَ في مخزنك لأشهر للحصول على أفضل النتائج. فعندما تصبح الفاصولياء قديمة، تحتاج إلى وقت أطول بكثير لتنضج ولا تصبح طرية جدًا. أحب فاصولياءي طرية وليست متهرئة، خاصة عند استخدامها في السلطات أو اللفائف، لذا أجد أن مدة ضغط 30 دقيقة تعطي أفضل فاصولياء سوداء في إنستانت بوت. وإذا كنت تستخدمها في الحساء وتفضّلها أطرى، فزد مدة الضغط إلى 35 دقيقة. التخزين: اترك الفاصولياء تبرد قليلًا قبل تخزينها، لكن لا تتركها في درجة حرارة الغرفة لأكثر من ساعتين وإلا بدأت البكتيريا بالنمو. تلميح: ضعها في أوعية عريضة قليلة العمق لتبرد أسرع، ثم ضعها في الثلاجة أو المجمّد. تُحفظ في الثلاجة لمدة 3-4 أيام في أكياس بسحّاب أو أوعية محكمة الإغلاق. وللتجميد، جفّف الفاصولياء بمنشفة مطبخ نظيفة. ثم قِس حوالي 1.5 كوب من الفاصولياء المطبوخة واحفظها في أكياس بسحّاب أو أوعية محكمة الإغلاق مناسبة للمجمّد. وهذا يعادل تقريبًا علبة فاصولياء بحجم 15 أونصة، مما يوفر حصصًا مريحة للوجبات المستقبلية. احرص على إخراج الهواء الزائد من الأكياس ذات السحّاب قبل التجميد لتدوم مدة أطول، ولتقل احتمالية تمزقها. احفظها مجمّدة لمدة تصل إلى 3 أشهر."],
{})
R(9784924,"دجاج البرتقال النباتي [خالٍ من الغلوتين والزيت]",
"دجاج برتقال نباتي طازج ولذيذ وسهل التحضير، سيجعل براعم التذوق لديك ترقص طربًا!",
"4 حصص","حصة واحدة",
["4 أونصات لفائف الصويا (حوالي نصف عبوة لفائف الصويا من Butler's)","8 أونصات فطر مقطع إلى شرائح","1 حبة فلفل رومي أحمر مقطعة إلى شرائح","1 كوب مرق خضار قليل الصوديوم","½ كوب عصير برتقال طازج (حوالي برتقالة كبيرة واحدة)","1 ملعقة صغيرة قشر برتقال مبشور","⅓ كوب خل الأرز","¼ كوب تاماري أو صلصة الصويا إن لم تكن تتجنب الغلوتين","¼ كوب شراب القيقب","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة زنجبيل مطحون","1 ملعقة كبيرة نشا الذرة أو 2 ملعقة كبيرة دقيق متعدد الاستخدامات","شعيرية (فيرميشيلي) أو أرز بني أو كينوا","بذور السمسم","بصل أخضر"],
["في وعاء متوسط، اخلط جميع مكونات التتبيلة، باستثناء نشا الذرة أو الدقيق، واخفقها جيدًا. ثم أضف لفائف الصويا إلى الوعاء وحرّك واتركها تنقع لمدة 10-15 دقيقة. تأكد من أنها كلها مغطاة بالتتبيلة.",
"في الأثناء، ضع الفطر والفلفل المقطعين إلى شرائح في مقلاة كبيرة. قلّبها دون إضافة دهون لتلين وتتقلص لمدة 4-5 دقائق. لن تحتاج إلى زيت أو ماء لأن الفطر سيُخرج سائله الخاص. وإذا التصق شيء، فأضف رشة من الماء.",
"بملعقة مثقبة أو ملقط، انقل لفائف الصويا المنقوعة إلى المقلاة مع الخضار واحتفظ بالصلصة. احرص على انتشال اللفائف من الوعاء ولا تسكبها سكبًا. قلّبها لمدة 5 دقائق لتتحمر حواف لفائف الصويا.",
"في الأثناء، أضف نشا الذرة إلى وعاء الصلصة وحرّك حتى يمتزج. ثم اسكب الصلصة في المقلاة مع اللفائف والخضار. اطبخها على نار متوسطة لمدة 3-5 دقائق حتى تثخن الصلصة، ثم قدّمها."],
["للحصول على طبق مقلي بصلصة أكثر، ضاعف كمية التتبيلة.","احرص على استخدام مرق خضار قليل الصوديوم للتتبيلة، لأن التاماري/صلصة الصويا يحتويان على كمية كبيرة من الملح. وإذا لم يكن لديك مرق قليل الصوديوم، فاستخدم نصف كوب من المرق مع نصف كوب من الماء.","لتقليل الصوديوم أكثر، استخدم تاماري قليل الصوديوم أو صلصة صويا قليلة الصوديوم.","لفائف الصويا ليست مثل قطع الصويا. تتوفر لفائف الصويا في معظم أقسام الأغذية الطبيعية أو متاجر الأغذية الصحية. أو يمكنك شراؤها من أمازون.","المعلومات الغذائية لربع وصفة دجاج البرتقال النباتي ولا تشمل الشعيرية أو الأرز."],
{"For the Marinade":"للتتبيلة","For serving":"للتقديم"})
R(9784963,"مافن خبز الموز بدقيق اللوز",
"مافن موز بدقيق اللوز رطب ومحلى بخفة ولذيذ بشكل لا يُصدَّق!",
"9 كعكات مافن","حصة واحدة",
["1¼ كوب موز مهروس من حوالي 3 حبات موز كبيرة ناضجة","⅓ كوب صلصة التفاح غير المحلاة","2 ملعقة كبيرة شراب القيقب","250 غرام دقيق اللوز المقشّر (حوالي 2.5 كوب إلا قليلًا)","1.5 ملعقة صغيرة بيكنغ باودر","½ ملعقة صغيرة بيكربونات الصوديوم","1 ملعقة صغيرة قرفة","½ كوب جوز أو بيكان مفروم"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية).",
"في وعاء خلط كبير، اهرس الموز وأضف صلصة التفاح وشراب القيقب. امزج جيدًا. ثم أضف الدقيق والبيكنغ باودر وبيكربونات الصوديوم والقرفة، وامزج حتى تمتزج. ثم أضف الجوز المفروم بطيّه برفق، إن استخدمته.",
"وزّع الخليط على 9 قوالب مافن. (استخدم قوالب غير لاصقة أو أكوابًا ورقية، أو ادهنها بالدهن عند الضرورة.) اخبزها لمدة 24-26 دقيقة، حتى تخرج عود الأسنان نظيفة عند غرسها في الوسط.",
"مهم: اترك المافن يرتاح في القالب لمدة 10-15 دقيقة قبل نقله إلى رف سلكي. سيكون المافن طريًا وهشًا عند خروجه من الفرن مباشرة، لكنه سيتماسك عند التبريد."],
["استخدم موزًا ناضجًا جدًا! تتطلب هذه الوصفة ملعقتين كبيرتين فقط من شراب القيقب، لذا استخدم موزًا شديد النضج وعلى قشره بقع بنية للحصول على حلاوة طبيعية.","زِن الدقيق. فالغرف من الكيس أقل دقة من الوزن. فإذا كان لديك ميزان مطبخ، فاستخدمه للحصول على أفضل قوام ونتائج.","استخدم بيكنغ باودر طازجًا. فالبيكنغ باودر المفتوح لأكثر من 6 أشهر قد تضعف فعاليته وقدرته على الرفع.","تختلف الأفران، لذا اخبز حتى تخرج عود الأسنان جافة ونظيفة عند غرسها في الوسط. وقد كان مافني مثاليًا في 24 دقيقة.","احفظ المتبقي في وعاء محكم الإغلاق أو ملفوفًا بإحكام في درجة حرارة الغرفة لمدة 1-2 يوم. وفي الثلاجة لمدة تصل إلى 5 أيام، أو جمّده في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Optional":"اختياري"})
R(9790342,"توفو مدخن",
"مدخن للغاية ومليء بالنكهة! هذا التوفو المدخن يستحق التجربة، ولا تحتاج حتى إلى مدخنة للحصول على هذه النتائج الرائعة.",
"4 حصص","حصة واحدة",
["350 غرام (12 أونصة) قالب توفو شديد الصلابة، اختر توفو عضويًا خاليًا من التعديل الوراثي إن أمكن","¼ كوب صلصة صويا قليلة الصوديوم أو تاماري للخالي من الغلوتين","¼ كوب ماء","3 ملاعق كبيرة شراب القيقب","1 ملعقة كبيرة دخان سائل","1 ملعقة كبيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الثوم","ما تبقى من التتبيلة المحتفظ بها","⅓ كوب ماء","1 ملعقة كبيرة نشا التابيوكا أو نشا الذرة"],
["قطّع قالب التوفو إلى مستطيلات بسماكة ¼ بوصة تقريبًا.",
"ثم ضع منشفة مطبخ نظيفة (أو مناديل ورقية) على لوح تقطيع ورتّب الشرائح فوقها في طبقة واحدة. ضع منشفة نظيفة أخرى فوق الشرائح، ثم لوح تقطيع آخر (أو صينية خبز مسطحة). وأخيرًا، ضع فوقها شيئًا ثقيلًا مثل مقلاة من الحديد الزهر أو كتبًا ثقيلة. اترك الأمر هكذا لمدة 15 دقيقة.",
"في الأثناء، ضع جميع مكونات التتبيلة في وعاء صغير وحرّك حتى تمتزج.",
"رتّب التوفو المعصور في طبق عريض قليل العمق في طبقة واحدة واسكب التتبيلة فوقه. ضعه في الثلاجة لمدة 60 دقيقة، وقلّب الشرائح بحذر عند منتصف المدة.",
"عندما يتبقى حوالي 10 دقائق من وقت النقع، سخّن الفرن مسبقًا على 400° فهرنهايت (205° مئوية) وبطّن صينية خبز بورق الزبدة. رتّب الشرائح في طبقة واحدة واخبزها لمدة 15 دقيقة. ثم اقلبها واخبزها 15-18 دقيقة أخرى.ملاحظة: احتفظ بسائل التتبيل!",
"سخّن شواية غير لاصقة، أو ادهن الشواية بقليل من الدهن إذا لزم الأمر.",
"اسكب ما تبقى من التتبيلة في قدر صغير وأضف ⅓ كوب من الماء وملعقة كبيرة من دقيق التابيوكا. اخفق جيدًا واتركها على نار متوسطة لمدة 2-3 دقائق لتثخن وتحصل على صلصة الشواء.",
"افرد الصلصة بالفرشاة على جانبي شرائح التوفو المدخن وضعها على الشواية بشكل قطري لتحصل على خطوط الشواء، حوالي 1-2 دقيقة لكل جانب."],
["خطّط مسبقًا! يمكنك تتبيل التوفو قبل يوم واحد لتوفير الوقت في يوم التقديم.","على الرغم من أن الوقت الكلي المطلوب يزيد قليلًا عن ساعتين، لاحظ أنه ليس كله وقتًا فعليًا للعمل، فالتوفو يُتبَّل في الثلاجة لمدة ساعة واحدة.","يُحفظ المتبقي في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق."],
{"For the marinade":"للتتبيلة","Optional: For grilling the smoked tofu":"اختياري: لشواء التوفو المدخن"})
R(9791180,"باستا بيستو الميسو",
"باستا بيستو الميسو طازجة وغنية بالنكهة بشكل لا يُصدَّق!",
"4 حصص","حصة واحدة",
["1.5 كوب أوراق ريحان طازجة مكبوسة برفق","½ كوب بذور عباد الشمس غير مملحة","3-4 فصوص ثوم","3 ملاعق كبيرة معجون الميسو الأبيض","3 ملاعق كبيرة خل التفاح","2-4 ملاعق كبيرة ماء مفلتر عند الحاجة","½ رطل فيتوتشيني أو شكل معكرونة من اختيارك"],
["اترك قدرًا كبيرًا من الماء المملح حتى يغلي واطبخ المعكرونة وفق تعليمات العبوة للحصول على معكرونة «ألدنتي». وإذا لم تتوفر تعليمات «ألدنتي» على العبوة، فاطبخ المعكرونة أقل من المدة بدقيقة إلى دقيقتين.",
"احتفظ بنصف كوب من ماء المعكرونة، ثم صفِّ المعكرونة وأعدها إلى القدر واتركها جانبًا.",
"في الأثناء، ضع جميع مكونات البيستو في محضّرة الطعام واخلطها حتى تمتزج، مع إضافة 2-4 ملاعق كبيرة من الماء عند الحاجة.",
"قلّب المعكرونة المطبوخة مع بيستو الميسو، وأضف من ماء المعكرونة المحتفظ به بالقدر الذي تريده لتخفيف الصلصة حسب ذوقك. ثم قدّمها."],
["استخدم بذور عباد الشمس غير المملحة لتجنب أن يصبح الطبق مالحًا جدًا.","أضف الملح إلى ماء الطبخ. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اطبخها حتى قوام «ألدنتي». لا تفرط في طبخها! «ألدنتي» تعني أن المعكرونة تبقى متماسكة بعد الطبخ، مما يعطي قوامًا مثاليًا في كل لقمة. ولتجنب الإفراط في الطبخ، ابدأ بتذوقها قبل بضع دقائق من الموعد المذكور على العبوة. يجب أن تكون طرية لكن متماسكة.","احتفظ بقليل من ماء الطبخ النشوي قبل تصفية المعكرونة لتخفيف صلصة بيستو الميسو حسب ذوقك."],
{})
